-- Latch coupling (crabbing) on a root-to-leaf descent:
node = root;  latch_read(node);
while (!node.is_leaf) {
    child = node.child_for(key);
    latch_read(child);        // acquire the child ...
    latch_release(node);      // ... BEFORE releasing the parent
    node = child;
}
-- The child latch is taken before the parent's is dropped, so no
-- concurrent split can detach the subtree under you.
-- Postgres also right-links every page, so a descent landing mid-split
-- moves right instead of restarting (Lehman-Yao, 1981).

// RocksDB. Levelled: one sorted run per level, size ratio T.
options.compaction_style = kCompactionStyleLevel;
options.max_bytes_for_level_multiplier = 10;           // T
options.max_bytes_for_level_base = 256 * 1024 * 1024;  // L1 target

// Tiered ("universal" in RocksDB): several runs per level.
options.compaction_style = kCompactionStyleUniversal;

// 1 TB data set, L1 = 256 MB, T = 10:
//   L = ceil(log10(1 TB / 256 MB)) = ceil(log10(4096)) = 4 levels
//   levelled  write amp ~ T*L = 40x   read amp ~ L   = 4
//   tiered    write amp ~ L   =  4x   read amp ~ T*L = 40

